fn fibonacci(n: usize) -> Vec<i32> {
    // Handle the base cases
    if n == 0 {
        return Vec::new();
    } else if n == 1 {
        return vec![0];
    }
    
    // Initialize the vector with the first two Fibonacci numbers
    let mut result = vec![0, 1];
    
    // Generate the remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}